mapper.select:
SELECT h.id, h.holding_no, h.user_id, u.username, h.product_id, p.product_code, p.product_name, p.product_type, p.annual_rate, a.account_no, h.amount, h.expected_income, h.actual_income, h.purchase_date, h.maturity_date, h.status FROM product_holding h LEFT JOIN sys_user u ON h.user_id = u.id AND u.deleted = 0 LEFT JOIN financial_product p ON h.product_id = p.id AND p.deleted = 0 LEFT JOIN account a ON h.account_id = a.id AND a.deleted = 0 WHERE h.deleted = 0
AND h.user_id = #{userId}
AND h.status = #{status}
ORDER BY h.create_time DESC
